/// ⭐ DB-402 (lane a 2026-10-27): THE WRITER LEDGER. Every manifest-ChainDerived field has ONE writer, the replay
/// function (src/node/replay.rs). This pin measures the writers still outside it with the guard's own regex over
/// the whole non-test source and holds the number as a ledger that only moves DOWN (a migration batch re-records
/// it; a new writer is refused at edit time by replicated-writer-guard.py and here). DONE = 0.
#[test]
fn every_chain_derived_writer_outside_the_replay_module_is_on_the_measured_ledger() {
    let (total, by_fn) = super::replay::ledger::writers_outside_replay();
    for (site, n) in &by_fn {
        eprintln!("[db402-writer] {site} ×{n}");
    }
    eprintln!("[db402-writer-ledger] {total} writes in {} functions outside src/node/replay.rs", by_fn.len());
    let ledger = super::replay::ledger::WRITERS_OUTSIDE_REPLAY_LEDGER;
    assert!(total <= ledger, "a NEW writer of a ChainDerived field outside src/node/replay.rs: {total} > ledger {ledger} — derive it in Node::derive_replicated (DB-402)");
    assert_eq!(total, ledger, "the writer ledger moved down to {total}: re-record WRITERS_OUTSIDE_REPLAY_LEDGER (it is the measurement, never a cap)");
}

/// A DAA window, newest first, `n` samples `dt_ms` apart (one blue block each), work moving linearly from `work_oldest`
/// to `work_newest` — the exact shape `daa_window_below` returns.
fn view_window(n: usize, dt_ms: u64, work_oldest: u128, work_newest: u128) -> Vec<crate::dag::DaaSample> {
    (0..n)
        .map(|i| {
            let from_newest = i as u128;
            let span = (n - 1) as u128;
            let work = (work_newest * (span - from_newest) + work_oldest * from_newest) / span;
            (1_000_000 - i as u64 * dt_ms, work, 10_000 - i as u64)
        })
        .collect()
}

/// ⛔ DB-380 (lane a 2026-10-26; T4, value class "a payment shown settled on a private chain") — THE WORK ARM READS A
/// DIFFICULTY FALL. `header.work` is the DIFFICULTY (`adaptive_work_checked`: slow blocks LOWER it), and an eclipsed
/// chain mined by a hash minority lets it fall; the arm read `newest / oldest`, so it fired on honest hash GROWTH and
/// was blind to the eclipse it was written for. Both directions at the target rate, where the rate arm is silent.
/// TWO-PARTY-REVIEWED: the verdict is a pure function of ONE node's own DAA window (node-local by spec, DB-380 §5); the
/// cross-party arms (victim vs honest origin on a 10-node wire) are the netsim `eclipse_a_victim_*` pins.
#[test]
fn view_quality_reads_a_difficulty_fall_as_degraded_and_a_difficulty_rise_as_trusted() {
    let fell = Node::view_quality_of(&view_window(16, 500, 5_000, 1_000), 500, 16);
    let rose = Node::view_quality_of(&view_window(16, 500, 1_000, 5_000), 500, 16);
    let flat = Node::view_quality_of(&view_window(16, 500, 3_000, 3_000), 500, 16);
    eprintln!("[view] fell {fell:?} · rose {rose:?} · flat {flat:?}");
    assert!(!flat.degraded, "CALIBRATION: a flat window at the target rate is trusted: {flat:?}");
    assert!(fell.degraded, "⛔ difficulty fell 5× inside one window (≥ DAA_CLAMP) and the view read trusted: {fell:?}");
    assert!(!rose.degraded, "⛔ difficulty ROSE 5× (honest hash growth) and the view read degraded: {rose:?}");
}

/// ⛔ DB-380 (lane a 2026-10-26; T4) — THE RATE ARM CATCHES ITS CLASS INSIDE THE ESTIMATOR'S SPREAD. The steady-state
/// rate of a k-producer eclipse is k / (relay floor 4 s ÷ target 500 ms) = k/8, so a 2-of-10 eclipse sits ON the 1/4
/// class boundary and a floor AT the boundary is a coin flip (MEASURED, same commit and seed: victim 0.231 degraded,
/// 0.327 trusted — watch-20261026-220001.log.2). The floor sits z = 3 relative standard deviations (1/√(n−1)) above
/// the boundary. Inputs are the measured victim (0.327) and the lowest measured honest view (0.71), at the netsim
/// window (16) and the production window (60).
/// TWO-PARTY-REVIEWED: a pure function of one node's own window (node-local verdict); the two-party arms are the
/// netsim `eclipse_a_victim_*` pins, victim against the honest origin.
#[test]
fn view_quality_catches_the_quarter_rate_class_inside_the_estimator_margin() {
    assert_eq!(Node::view_rate_floor_x1000(16), 443, "class 250 × (1 + 3/√15)");
    assert_eq!(Node::view_rate_floor_x1000(60), 347, "class 250 × (1 + 3/√59)");
    let victim = Node::view_quality_of(&view_window(16, 1_530, 1, 1), 500, 16);
    let honest = Node::view_quality_of(&view_window(16, 704, 1, 1), 500, 16);
    let victim60 = Node::view_quality_of(&view_window(60, 1_530, 1, 1), 500, 60);
    let honest60 = Node::view_quality_of(&view_window(60, 704, 1, 1), 500, 60);
    eprintln!("[view] victim {victim:?} · honest {honest:?} · victim60 {victim60:?} · honest60 {honest60:?}");
    assert!(!honest.degraded && !honest60.degraded, "CALIBRATION: the lowest measured honest rate (0.71) stays trusted: {honest:?} {honest60:?}");
    assert!(victim.degraded, "⛔ the measured eclipsed victim (rate ~0.33, the 2-of-10 class) read trusted: {victim:?}");
    assert!(victim60.degraded, "⛔ the same class at the production window read trusted: {victim60:?}");
}

/// ⛔⛔⛔ DB-354 (lane a 2026-10-24; T2/G2) — A PRODUCER RECORDS WHAT ITS PEER'S DOOR ADMITS, NEVER ITS RAW BODY.
/// Every ingest writer records `graft_admitted_notes(..)` over a block's notes; the produce path recorded
/// `block.output_notes` raw. A note nothing on the block justifies (here a BridgeCredit one unit over the open-mint
/// allowance with no quorum) was then in the PRODUCER's record and in no peer's: the record, the note frontier and
/// every root built on it were a function of which node mined, and the producer's wallet saw value no node created.
/// TWO-PARTY-REVIEWED: the producer's own record against the record of a peer that only grafts its block.
#[test]
fn db354_a_producer_records_only_the_notes_its_peer_admits() {
    const N: usize = 1153;
    let mut producer = Node::new_folding_at_tip_for_test(genesis_block()).unwrap();
    let mut peer = Node::new_folding_at_tip_for_test(genesis_block()).unwrap();
    let mut note = vec![0u8; N];
    note[..32].copy_from_slice(&[0xD5u8; 32]);
    producer.record_note_payload(0, &note); // stages the note into the next produced block's lane
    producer.stage_credit_justifier(
        crate::bridge_credit_tx::BridgeCreditTx {
            deposit_id: [0xD5u8; 32],
            asset_tag: usdm_decider::whir_rec_block::USDM_ASSET_TAG,
            amount: producer.params().genesis_mint_allowance() + 1,
            note: note.clone(),
            owner_clue: Vec::new(),
            attestors: Vec::new(),
        }
        .wire(),
    );
    let blk = producer
        .produce(5_000, Hash32::hash(b"carrier-frontier"), Hash32::hash(b"carrier-miner"))
        .expect("the producer lays its block");
    assert!(crate::block::credit_set_has_entries(&blk.credit_set, crate::block::credit_seal_key(&blk.header, blk.cover_key.as_ref()).as_ref()), "CONTROL: the block carries the unjustified credit object");
    assert!(
        blk.output_notes.chunks(N).any(|c| c.len() == N && c[..32] == [0xD5u8; 32]),
        "CONTROL: the block's body carries the credit's note"
    );
    assert!(matches!(peer.ingest_block(blk.clone(), 6_000), RelayOutcome::Added(_)), "PRECONDITION: the peer grafts the block");
    let holds = |n: &Node| n.da_recorded_notes().iter().any(|(_, b)| b.chunks(N).any(|c| c.len() == N && c[..32] == [0xD5u8; 32]));
    assert!(!holds(&peer), "CALIBRATION: the peer's graft door refuses the unjustified note");
    assert_eq!(
        producer.admitted_real_notes_of(&blk.id()),
        peer.admitted_real_notes_of(&blk.id()),
        "⛔ DB-354: the producer's own record of its block differs from the peer's record of the SAME block"
    );
    assert!(!holds(&producer), "⛔⛔⛔ DB-354: the producer self-recorded a note every peer's door refuses — value no node created");
}

/// §RF-3 (lane a 2026-10-24; R5): AN IDLE BLOCK'S RECORD IS UNPARTITIONABLE BY A NON-HOLDER (spec §2.4/§2.5).
/// A non-holder knows a block's record address (a function of its id) and nothing else. If the 256 units the
/// producer serves for an idle block equal what that address alone regenerates, the non-holder names every
/// idle block — a one-bit quiet/busy oracle per record (cover.rs DB-165 note) and, through spec §13's
/// HEADER_SEED-from-bodies, every cover cm and decoy tag of that block. MEASURED in code 2026-10-24: the idle
/// record's reals are `cover::public_idle_seed_note(addr)` (node.rs `regenerate_idle_record`, `da_record_reals`).
#[test]
fn an_idle_blocks_record_is_not_reproducible_from_its_address_alone() {
    // A rewarded block already carries the producer's sealed reward note (private seal seed), so the idle case is
    // a producer with NO reward recipient and an empty pool — the block whose reals would otherwise be nothing.
    let mut a = testnet_party_with_fold_depth(0);
    a.reward_recipient = None;
    assert!(a.pending_credit_notes.is_empty(), "PRECONDITION: no staged credit rides the block");
    let spacing = a.params().target_spacing_ms;
    let now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + spacing;
    let blk = a
        .produce(now, Hash32::hash(b"rf3-idle-f"), Hash32::hash(b"rf3-idle-m"))
        .expect("A produces an idle block");
    assert!(blk.tx_ids.iter().all(|t| a.mempool.get(t).is_none()), "PRECONDITION: no pooled tx rides the block");
    let addr = a.record_addr_for_block_or_canonical(&blk.id());
    let served = a.da_record_notes(addr).expect("PRECONDITION: the producer serves the idle block's record");
    assert_eq!(served.len(), crate::cover::BLOCK_FIXED_NOTE_COUNT * crate::cover::PQ_NOTE_BYTES, "constant shape");
    let from_address_alone =
        crate::cover::assemble_fixed_note_payload(&crate::cover::public_idle_seed_note(addr), addr, &crate::cover::idle_cover_key(addr));
    assert_ne!(
        served, from_address_alone,
        "⛔ R5: a non-holder regenerates the idle block's 256 units from its address alone — the block is named idle"
    );
    // ASSERT WHAT THE PEER HOLDS: a verifying peer fed only the block admits the seed note through its door and
    // serves the producer's exact record (record == serve across nodes).
    assert_eq!(blk.output_notes.len(), crate::cover::PQ_NOTE_BYTES, "the no-recipient block carries one seed note");
    assert!(crate::cover::is_seed_note_in(&blk.output_notes, &blk.output_notes, &kb(&blk)), "calibration: the carried note is the seed");
    let mut b = testnet_party_with_fold_depth(0);
    assert!(matches!(b.ingest_block(blk.clone(), now + 500), RelayOutcome::Added(_)), "the peer grafts the block");
    let gid = blk.id();
    let door = |notes: &[u8]| b.graft_admitted_notes(&gid, notes, blk.cover_key, None, None, None, &[], &[], &[], &[], &[]);
    assert_eq!(door(&blk.output_notes), blk.output_notes, "⛔ the peer's door refused the honest seed note");
    let b_addr = b.record_addr_for_block_or_canonical(&gid);
    assert_eq!(b_addr, addr, "both nodes address the block alike");
    assert_eq!(
        b.da_record_notes(b_addr).as_deref(),
        Some(served.as_slice()),
        "⛔ the peer does not hold the producer's record of the seeded block"
    );
    // TAMPERS — the seed rule admits exactly one well-formed seed and nothing else.
    let mut forged = blk.output_notes.clone();
    forged[40] ^= 1; // body changed, front kept: the front is no longer the cover cell of THIS body's seed (§18.1)
    assert!(door(&forged).is_empty(), "⛔ a seed note whose cm is not its body's hash was admitted");
    let mut two = blk.output_notes.clone();
    two.extend_from_slice(&crate::cover::fresh_seed_note());
    assert!(door(&two).is_empty(), "⛔ a block carrying TWO unjustified seed notes had one admitted");
    let plain = crate::cover::cover_note().expect("a cover note");
    assert!(door(&plain).is_empty(), "⛔ an ordinary unjustified note was admitted as a seed");
}

/// ⭐ §RF-3 spec §2.4/§13 (lane a 2026-10-24; R5): A BLOCK'S 256 HEADER NOTE SLOTS ARE ITS LEDGER'S 256 OUT CELLS.
/// The ledger states every non-spend out cell as a justified note or `cover_note_native(HEADER_SEED, slot)`
/// (`plan_ledger_rows`); a header cover unit wearing any other front lets `list ∩ header` name the real cells — and a
/// front that is not a canonical digest names them by its encoding alone. HEADER_SEED = `cover::header_seed(reals)`
/// (bodies only). Quiet (the seed note) and rewarded blocks alike; the peer serves the same 256 slots.
#[test]
fn rf3_ledger_out_cells_are_the_header_note_slots() {
    use crate::cover::{BLOCK_FIXED_NOTE_COUNT, PQ_NOTE_BYTES};
    use crate::spend_frontier::leaf_to_cm_bytes;
    use usdm_decider::slot_ledger::{cover_note_native, CELLS_PER_ROW};
    for rewarded in [false, true] {
        let mut a = testnet_party_with_fold_depth(0);
        if !rewarded {
            a.reward_recipient = None;
        }
        let spacing = a.params().target_spacing_ms;
        let now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + spacing;
        let blk = a
            .produce(now, Hash32::hash(b"rf3-slots-f"), Hash32::hash(b"rf3-slots-m"))
            .expect("A produces a block");
        let addr = a.record_addr_for_block_or_canonical(&blk.id());
        let served = a.da_record_notes(addr).expect("PRECONDITION: the producer serves the block's record");
        let reals = &blk.output_notes;
        assert!(!reals.is_empty() && reals.len() % PQ_NOTE_BYTES == 0, "PRECONDITION: whole real notes ride the block");
        let header = crate::note_transition::header_note_cms(&served).expect(
            "⛔ R5: a header note front is not a canonical digest — a cover slot is told from a real cm by its encoding",
        );
        let justified: Vec<crate::spend_frontier::Digest4> = reals
            .chunks_exact(PQ_NOTE_BYTES)
            .map(|u| crate::spend_frontier::note_cm_of(u).expect("a real note's front is a canonical digest"))
            .collect();
        let seed = crate::cover::header_seed(reals, &kb(&blk));
        let rows = usdm_decider::settlement_delta::plan_ledger_rows(seed, 0, &justified, &[], &|_, _| {
            Some(usdm_decider::poseidon2_compress::zero_digest())
        })
        .expect("the block is stateable");
        let mut cells: Vec<[u8; 32]> = rows
            .iter()
            .flat_map(|r| {
                let w = r.witness.clone();
                (0..CELLS_PER_ROW).map(move |k| {
                    leaf_to_cm_bytes(if w.j[k] { w.just_n[k] } else { cover_note_native(seed, w.slots[CELLS_PER_ROW + k]) })
                })
            })
            .collect();
        let mut slots = header.clone();
        cells.sort_unstable();
        slots.sort_unstable();
        assert_eq!(cells.len(), BLOCK_FIXED_NOTE_COUNT, "the ledger states 256 out cells");
        assert!(
            cells == slots,
            "⛔ R5 (rewarded={rewarded}): the header's note slots are not the ledger's out cells — list ∩ header names the reals"
        );
        // ASSERT WHAT THE PEER HOLDS: a verifying peer fed only the block serves the same 256 slots.
        let mut b = testnet_party_with_fold_depth(0);
        assert!(matches!(b.ingest_block(blk.clone(), now + 500), RelayOutcome::Added(_)), "the peer grafts the block");
        let b_addr = b.record_addr_for_block_or_canonical(&blk.id());
        assert_eq!(b.da_record_notes(b_addr).as_deref(), Some(served.as_slice()), "⛔ the peer serves other slots");
        // The law can fail: one cover unit wearing a cell the ledger does not state breaks the equality.
        let mut tampered = served.clone();
        let last = (BLOCK_FIXED_NOTE_COUNT - 1) * PQ_NOTE_BYTES;
        tampered[last..last + 32].copy_from_slice(&leaf_to_cm_bytes(cover_note_native(seed, 9_999)));
        let mut t = crate::note_transition::header_note_cms(&tampered).expect("canonical fronts");
        t.sort_unstable();
        assert_ne!(t, cells, "calibration: a moved cover front breaks the equality");
    }
}

/// ⭐ §RF-3 spec §15 (lane a 2026-10-24; R5): A BLOCK'S 256 PADDED TAGS ARE ITS LEDGER'S 256 TAG CELLS.
/// The ledger states every non-spend tag cell as a justified tag or `cover_tag_native(HEADER_SEED, slot)`
/// (`plan_ledger_rows`); a header decoy wearing any other value lets `list ∩ header` name the block's real tags.
/// HEADER_SEED = `cover::header_seed(reals)` — never the record address, which the id derives from the very tags
/// it would seed (§15). Quiet, rewarded and spend-bearing blocks alike; an honest peer grafts the block.
#[test]
fn rf3_ledger_tag_cells_are_the_header_padded_tags() {
    use crate::cover::BLOCK_FIXED_NULLIFIER_COUNT;
    use crate::spend_frontier::{cm_bytes_to_root, leaf_to_cm_bytes};
    use usdm_decider::slot_ledger::{cover_tag_native, CELLS_PER_ROW};
    for case in ["quiet", "rewarded", "busy"] {
        let busy = case == "busy";
        let fresh = || if busy { Node::new(genesis_block()).unwrap() } else { testnet_party_with_fold_depth(0) };
        let mut a = fresh();
        if case == "quiet" {
            a.reward_recipient = None;
        }
        let mut reals: Vec<[u8; 32]> = Vec::new();
        let now = if busy {
            let mut d = usdm_decider::poseidon2_compress::zero_digest();
            d[0] = 0x5eed;
            d[2] = 77;
            let nf = Hash32(leaf_to_cm_bytes(d)); // a canonical tag, as every real nullifier is
            let need = a.mempool().required_stamp_bits();
            a.ingest_tx_unverified(grind_tx(b"rf3-tags-busy", 1000, vec![nf], need)).expect("the node pools a spend");
            reals.push(nf.0);
            5_000
        } else {
            a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + a.params().target_spacing_ms
        };
        let blk = a.produce(now, Hash32::hash(b"rf3-tags-f"), Hash32::hash(b"rf3-tags-m")).expect("A produces a block");
        let padded = blk.nullifier_proof.padded_tags.clone();
        assert_eq!(padded.len(), BLOCK_FIXED_NULLIFIER_COUNT, "PRECONDITION: the constant tag width");
        assert!(reals.iter().all(|r| padded.contains(r)), "PRECONDITION: every real tag rides the block");
        // The block's other real tags (its reward's nullifier, its objects' own) are what the PEER's lane rule
        // justifies from the body — read on a node that did not produce it.
        let just = fresh().lane_justified(&blk);
        let more: Vec<[u8; 32]> = padded.iter().filter(|t| just.holds(t) && !reals.contains(t)).copied().collect();
        reals.extend(more);
        if case != "quiet" {
            assert!(reals.len() > usize::from(busy), "PRECONDITION ({case}): the reward's nullifier rides the lane");
        }
        assert!(
            padded.iter().all(|t| cm_bytes_to_root(t).is_some()),
            "⛔ R5 ({case}): a padded tag is not a canonical digest — a decoy is told from a real tag by its encoding"
        );
        let justified: Vec<crate::spend_frontier::Digest4> =
            reals.iter().map(|t| cm_bytes_to_root(t).expect("a canonical real tag")).collect();
        let seed = crate::cover::header_seed(&blk.output_notes, &kb(&blk));
        let rows = usdm_decider::settlement_delta::plan_ledger_rows(seed, 0, &[], &justified, &|_, _| {
            Some(usdm_decider::poseidon2_compress::zero_digest())
        })
        .expect("the block is stateable");
        let mut cells: Vec<[u8; 32]> = rows
            .iter()
            .flat_map(|r| {
                let w = r.witness.clone();
                (0..CELLS_PER_ROW)
                    .map(move |k| leaf_to_cm_bytes(if w.t[k] { w.just_t[k] } else { cover_tag_native(seed, w.slots[k]) }))
            })
            .collect();
        let mut tags = padded.clone();
        cells.sort_unstable();
        tags.sort_unstable();
        assert_eq!(cells.len(), BLOCK_FIXED_NULLIFIER_COUNT, "the ledger states 256 tag cells");
        assert!(cells == tags, "⛔ R5 ({case}): the header's padded tags are not the ledger's tag cells — list ∩ header names the reals");
        // ASSERT WHAT THE PEER HOLDS: an honest peer fed only the block grafts it (its fold verifies over these tags).
        let mut b = fresh();
        assert!(matches!(b.ingest_block(blk.clone(), now + 500), RelayOutcome::Added(_)), "⛔ the peer refused the block");
        // The law can fail: one decoy the ledger does not state breaks the equality.
        let mut t = tags.clone();
        let i = t.iter().position(|x| !reals.contains(x)).expect("a decoy");
        t[i] = leaf_to_cm_bytes(cover_tag_native(seed, 9_999));
        t.sort_unstable();
        assert_ne!(t, cells, "calibration: a moved decoy breaks the equality");
    }
}

/// §RF-3 wiring (lane a 2026-10-24; R5): the ledger a producer lays over a SEALED block from its carried bytes alone
/// (`note_transition::block_ledger_inputs` → `build_ledger_with`) is admitted by the door against THAT block's served
/// header slots, padded tags and seed commit — quiet and rewarded alike, one wire length — and refused under a foreign
/// seed commit or a moved decoy. The producer↔door agreement the per-block wiring stands on. `armed`: the bound double
/// (`real`: the WHIR prove, run once by [`rf3_a_quiet_blocks_real_ledger_costs_and_verifies`]).
fn rf3_produced_ledger_case(rewarded: bool, armed: bool) -> (usize, usize) {
    let mut a = testnet_party_with_fold_depth(0);
    if !rewarded {
        a.reward_recipient = None;
    }
    let now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + a.params().target_spacing_ms;
    let blk = a.produce(now, Hash32::hash(b"rf3-wire-f"), Hash32::hash(b"rf3-wire-m")).expect("A produces a block");
    let served = a.da_record_notes(a.record_addr_for_block_or_canonical(&blk.id())).expect("the record is served");
    let hcms = crate::note_transition::header_note_cms(&served).expect("256 canonical header slots");
    let padded = blk.nullifier_proof.padded_tags.clone();
    let (jn, jt, seed) = crate::note_transition::block_ledger_inputs(&blk.output_notes, &padded, &[], &kb(&blk))
        .expect("⛔ a sealed block's justified cells are not stateable");
    let onr = blk.header.output_notes_root;
    // MEASURED 2026-10-24 (RED, scratchpad/night/rf3-wire-r1.log): over the block's own `oli_tags` (its real notes
    // only) the producer lays NOTHING — the ledger door requires the uniform filing (§10 C1, every published note,
    // ascending). So the per-block wiring re-files `oli_tags` as `uniform_ledger_filing` BEFORE `oli_tags_root`.
    assert!(
        crate::note_transition::build_ledger_with(&[], &jn, &jt, seed, &onr, &blk.oli_tags, true).is_none(),
        "calibration: a ledger over the block's real-only filing is refused (§10 C1)"
    );
    let filing = crate::note_transition::uniform_ledger_filing(&[], &jn, &jt, seed, &blk.oli_tags)
        .expect("⛔ the sealed block's filing cannot be made uniform");
    // R4 lever 4 C2: the REAL ledger is one joined proof with the member ledger (no stated spend: the null member
    // carrier, under a ring this test names); the armed double keeps its own seals, its member seal judged apart.
    let lanes = usdm_decider::poseidon2_compress::lanes_of;
    let ring = [lanes(&[0xdec0, 1]), lanes(&[0xdec0, 2])];
    let rc = crate::member_transition::ring_commit_of(&ring).expect("the ring states");
    let t0 = std::time::Instant::now();
    let (nt, commit) = if armed {
        crate::note_transition::build_ledger_with(&[], &jn, &jt, seed, &onr, &filing, true).map(|(nt, c, _)| (nt, c))
    } else {
        crate::note_transition::build_ledger(&[], &[], &ring, &jn, &jt, seed, &onr, &filing)
    }
    .expect("⛔ the producer cannot lay a ledger over its own sealed block");
    let build_ms = t0.elapsed().as_millis();
    let door_under = |nt: &crate::note_transition::NoteTransition, c: &Hash32, tags: &[[u8; 32]], rc: &Hash32| {
        if armed {
            crate::note_transition::verify_ledger_with(nt, &onr, c, &filing, &hcms, tags, true).is_some()
        } else {
            crate::note_transition::verify_ledger(nt, &onr, c, &filing, &hcms, tags, rc).is_some()
        }
    };
    let door = |nt: &crate::note_transition::NoteTransition, c: &Hash32, tags: &[[u8; 32]]| door_under(nt, c, tags, &rc);
    if !armed {
        let foreign_ring = crate::member_transition::ring_commit_of(&[ring[0], lanes(&[0xdec1])]).expect("a foreign ring states");
        // V2: the joined proof carries no member statement, so the door does not read the ring commit — the fold judges it
        // (`Node::member_anchors_at_fold`: `member_ring_commit_is_canonical`, then each spend's own anchor)
        assert!(door_under(&nt, &commit, &padded, &foreign_ring), "the door does not judge the ring commit (the fold does)");
    }
    let t1 = std::time::Instant::now();
    assert!(door(&nt, &commit, &padded), "⛔ R5 (rewarded={rewarded}): the door refuses the honest producer's ledger");
    let verify_ms = t1.elapsed().as_millis();
    let foreign = crate::block::cover_seed_commit_of(usdm_decider::poseidon2_compress::lanes_of(&[9, 9, 9, 9]));
    assert!(!door(&nt, &foreign, &padded), "⛔ a ledger admitted under a foreign seed commit");
    let mut moved = padded.clone();
    let i = moved.iter().position(|t| !jt.iter().any(|j| crate::spend_frontier::leaf_to_cm_bytes(*j) == *t)).expect("a decoy");
    moved[i] = crate::spend_frontier::leaf_to_cm_bytes(usdm_decider::slot_ledger::cover_tag_native(seed, 9_999));
    assert!(!door(&nt, &commit, &moved), "⛔ a ledger admitted against a moved decoy");
    eprintln!(
        "[rf3-cost] armed={armed} rewarded={rewarded} build_ms={build_ms} verify_ms={verify_ms} agg_B={} tuples_B={} oli_B={}",
        nt.agg.len(),
        nt.tuples.len(),
        filing.len()
    );
    (nt.agg.len(), nt.tuples.len() + filing.len())
}

/// §RF-3 peer-door input (lane a 2026-10-24; R5): the header slots a door derives from a block's CARRIED real notes
/// (`note_transition::header_note_cms_of_bodies`) are exactly the 256 slots its served DA record holds — quiet and
/// rewarded alike — so the graft / fold / lane-justify doors can verify a ledger from the body alone. Calibration: a
/// body with one real note dropped states different slots.
/// §RF-3 (R5) — PRODUCE LAYS THE LEDGER: once A's ring is complete, A's quiet block carries the constant-shape ledger
/// (note ledger + member ledger, header seed + ring commit, uniform filing) from `produce` itself, and a SECOND armed
/// node B grafts it and the next one through its own door — B holds A's tip. RED on 5f10e53: produce laid no
/// transition on a quiet block. TWO-PARTY-REVIEWED: A builds, B's ingest door judges; the assertion is B's DAG.
#[test]
fn rf3_a_produced_quiet_ledger_block_grafts_on_an_armed_peer() {
    let (mut a, mut b) = (testnet_party_with_fold_depth(0), testnet_party_with_fold_depth(0));
    for n in [&mut a, &mut b] {
        n.reward_recipient = None;
        n.arm_template_double_for_test();
    }
    let class = crate::note_transition::ledger_shape_wire().expect("the ledger class states");
    let mut now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp;
    for i in 0..3u8 {
        now += a.params().target_spacing_ms;
        // Block 0 is produced before the ring completes (the legacy shape); every block after lays the ledger.
        let rc = a.current_member_ring_commit();
        let blk = a.produce(now, Hash32::hash(&[b'f', i]), Hash32::hash(&[b'm', i])).expect("A produces");
        let Some(rc) = rc else {
            assert!(i == 0, "calibration: A's ring is complete after its first fold step");
            let id = blk.id();
            assert!(matches!(b.ingest_block(blk, now + 100), crate::relay::RelayOutcome::Added(_)), "B grafts block 0");
            assert_eq!(b.selected_tip(), Some(id), "B holds A's tip after block 0");
            continue;
        };
        let nt = blk.note_transition.as_ref().expect("⛔ R5: A's quiet block lays no ledger");
        assert_eq!(nt.shape, class, "⛔ R5: the quiet block's transition is not the ledger class");
        let mt = blk.member_transition.as_ref().expect("⛔ R5: a ledger block without its member ledger");
        assert_eq!((mt.shape, mt.tuples.len()), (class, 0), "the member ledger is the ledger class, list derived");
        assert_eq!(blk.header.member_ring_commit, rc, "the header names A's standing ring");
        assert_ne!(blk.header.cover_seed_commit, Hash32::default(), "the header names the ledger's seed commit");
        let id = blk.id();
        let got = b.ingest_block(blk, now + 100);
        assert!(matches!(got, crate::relay::RelayOutcome::Added(_)), "⛔ R5: B refuses A's ledger block {i}: {got:?}");
        assert_eq!(b.selected_tip(), Some(id), "⛔ B does not hold A's tip after block {i}");
    }
}

/// §RF-3 (R5) — A BUSY LEDGER BLOCK IS A QUIET ONE'S SHAPE: A lays a quiet ledger block, then one carrying a FUNDED
/// honest spend with its member leg (`honest_spend_tx_for_test`); armed peer B grafts both through its own door, and
/// B's FOLD then holds the spend's tags (the stated row was admitted, not skipped). Every transition field and the
/// filing weigh the same bytes on both blocks — an observer cannot separate the spending block from the quiet one.
/// TWO-PARTY-REVIEWED: A builds, B's door and fold judge; the assertions are B's DAG and B's spent set.
#[test]
fn rf3_a_produced_busy_ledger_block_grafts_on_an_armed_peer_in_the_quiet_shape() {
    let (mut a, mut b) = (testnet_party_with_fold_depth(0), testnet_party_with_fold_depth(0));
    for n in [&mut a, &mut b] {
        n.reward_recipient = None;
        n.arm_template_double_for_test();
    }
    let shape = |blk: &crate::block::Block| {
        let w = |v: Option<Vec<u8>>| v.map_or(0, |v| v.len());
        [
            blk.note_transition.as_ref().map_or(0, |n| n.agg.len()),
            blk.note_transition.as_ref().map_or(0, |n| n.tuples.len()),
            blk.member_transition.as_ref().map_or(0, |t| t.agg.len()),
            blk.member_transition.as_ref().map_or(0, |t| t.tuples.len()),
            w(blk.cover_transition.as_ref().and_then(|c| postcard::to_allocvec(c).ok())),
            blk.oli_tags.len(),
            w(postcard::to_allocvec(&blk.nullifier_proof).ok()),
            blk.tx_ids.len() * 32,
        ]
    };
    let mut now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp;
    let mut lay = |a: &mut Node, b: &mut Node, now: u64, tag: u8| {
        let blk = a.produce(now, Hash32::hash(&[b'f', tag]), Hash32::hash(&[b'm', tag])).expect("A produces");
        let (id, s) = (blk.id(), shape(&blk));
        let got = b.ingest_block(blk.clone(), now + 100);
        assert!(matches!(got, crate::relay::RelayOutcome::Added(_)), "⛔ R5: B refuses A's block {tag}: {got:?}");
        assert_eq!(b.selected_tip(), Some(id), "⛔ B does not hold A's tip after block {tag}");
        let _ = b.fold_canonical_records();
        (blk, s)
    };
    now += a.params().target_spacing_ms;
    let _ = lay(&mut a, &mut b, now, 0); // the ring completes after A's first fold step
    assert!(a.current_member_ring_commit().is_some(), "calibration: A's ring is complete");
    now += a.params().target_spacing_ms;
    let (quiet, quiet_shape) = lay(&mut a, &mut b, now, 1);
    assert!(quiet.note_transition.is_some(), "calibration: the quiet block lays the ledger");
    let spend = honest_spend_tx_for_test(&mut a, &mut [&mut b], 0x5f3);
    // The spend's tag list is its nullifier and claim tag among decoys: B's spent set must come to hold exactly two.
    let spent_on_b = |b: &Node| spend.nullifiers.iter().filter(|t| b.is_nullifier_spent(t)).count();
    assert_eq!(spent_on_b(&b), 0, "calibration: B holds none of the spend's tags before the busy block");
    let sid = spend.id;
    // TAMPER (canonical-tag law): the same spend with ONE decoy swapped for a blake3 pad is refused at B's gossip
    // door before any verify — it would force the legacy count-stating block. Tampered first: the honest copy shares
    // its id, so pooling it first would answer AlreadyKnown and prove nothing.
    let mut forged = spend.clone();
    forged.nullifiers[2] = Hash32::hash(b"rf3-blake3-pad");
    let got = b.ingest_tx(forged);
    assert!(matches!(got, Err(MempoolError::NonCanonicalTag)), "⛔ R5: a blake3-padded spend reached B's pool: {got:?}");
    let got = b.ingest_tx(spend.clone());
    assert!(!matches!(got, Err(MempoolError::NonCanonicalTag)), "calibration: the honest spend's tags are canonical");
    a.ingest_tx_unverified(spend.clone()).expect("A pools the stated spend");
    now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + a.params().target_spacing_ms;
    let (busy, busy_shape) = lay(&mut a, &mut b, now, 2);
    assert!(busy.tx_ids.contains(&sid), "calibration: the busy block carries the spend");
    // Every input `ledger_lay_of` reads, named, so a legacy-shaped busy block says WHICH one refused.
    let tuple = Node::spend_tuple_of(&spend).expect("calibration: the spend states a tuple");
    let fronts: Vec<[u8; 32]> =
        busy.output_notes.chunks_exact(crate::cover::PQ_NOTE_BYTES).map(|n| n[..32].try_into().expect("32")).collect();
    let padded = &busy.nullifier_proof.padded_tags;
    eprintln!(
        "[rf3-busy] ring {} hcms {} inputs(quiet-form) {} inputs(stated) {} out0 {} out1 {} nf {} tag1 {} notes {} padded {}",
        a.current_member_ring_commit().is_some(),
        crate::note_transition::header_note_cms_of_bodies(&busy.output_notes, &kb(&busy)).is_some(),
        crate::note_transition::block_ledger_inputs(&busy.output_notes, padded, &[], &kb(&busy)).is_some(),
        crate::note_transition::block_ledger_inputs(&busy.output_notes, padded, std::slice::from_ref(&tuple), &kb(&busy)).is_some(),
        fronts.contains(&tuple.out0_cm),
        fronts.contains(&tuple.out1_cm),
        padded.contains(&tuple.nullifier),
        padded.contains(&tuple.tag1),
        fronts.len(),
        padded.len()
    );
    let class = crate::note_transition::ledger_shape_wire().expect("the ledger class states");
    let nt = busy.note_transition.as_ref().expect("⛔ R5: the busy block lays no ledger");
    let mt = busy.member_transition.as_ref().expect("⛔ R5: a busy ledger block without its member ledger");
    assert_eq!((nt.shape, mt.shape, mt.tuples.len()), (class, class, 0), "⛔ R5: the busy block is not the ledger class");
    // RE-STATED 2026-10-27 (lane funds; read RED "left: 32" since 2026-10-25, red-origin.tsv): B's admitted set holds the
    // spend's WHOLE constant width — the stated row's two tags (nullifier, claim) through the ledger door AND its other 30
    // through the block's spend-or-decoy transition (`verify_cover_with`: "every carried tag enters the allow-list, real
    // and decoy alike", DB-83 — the set grows by exactly `TX_FIXED_NULLIFIER_COUNT` per spend whatever k was; every wallet
    // send carries the carrier, `pending_cover_for`). The "2" this pin opened with described the ledger alone; fewer than
    // the width is a REAL tag left spendable, more is a tag no statement admitted — both refused here.
    assert_eq!(
        spent_on_b(&b),
        crate::cover::TX_FIXED_NULLIFIER_COUNT,
        "⛔ R5: B grafted the busy block but did not admit the spend's whole constant-width tag set (its row's two and its cover width)"
    );
    eprintln!("[rf3-busy] quiet {quiet_shape:?} busy {busy_shape:?}");
    assert_eq!(busy_shape, quiet_shape, "⛔ R5: a busy ledger block and a quiet one differ on the wire");
}

/// ⭐ §BR-14 — EVERY APPLIED SPEND CREDITS THE FLAT FEE TO THE FOUR POOLS, ON EVERY NODE. A lays a quiet ledger block (the
/// pools stay empty: a cover row pays nothing), then one carrying a funded honest spend; armed peer B grafts both through
/// its own door and folds them. Both nodes' pools then hold exactly ONE protocol fee, split 40/25/25/10 — one value on
/// both, because the credit is a function of the folded chain. TAMPER: the same shape of spend paying NO fee fails the
/// door's carrier check (`send_verdict`'s spend arm) under the protocol fee every node supplies, while its carrier is honest
/// under fee 0 — so the weld, and nothing earlier, is what refuses it.
/// TWO-PARTY-REVIEWED: A builds and B judges; the assertions are both nodes' pools and B's door.
#[test]
fn br14_every_applied_spend_credits_the_flat_fee_to_the_four_pools_on_every_node() {
    let f = usdm_decider::whir_rec_block::PROTOCOL_FEE_ATOMIC;
    let (mut a, mut b) = (testnet_party_with_fold_depth(0), testnet_party_with_fold_depth(0));
    for n in [&mut a, &mut b] {
        n.reward_recipient = None;
        n.arm_template_double_for_test();
    }
    let lay = |a: &mut Node, b: &mut Node, now: u64, tag: u8| -> crate::block::Block {
        let blk = a.produce(now, Hash32::hash(&[b'F', tag]), Hash32::hash(&[b'M', tag])).expect("A produces");
        let got = b.ingest_block(blk.clone(), now + 100);
        assert!(matches!(got, crate::relay::RelayOutcome::Added(_)), "B refuses A's block {tag}: {got:?}");
        let _ = b.fold_canonical_records();
        let _ = a.fold_canonical_records();
        blk
    };
    let next = |a: &Node| a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + a.params().target_spacing_ms;
    let t = next(&a);
    lay(&mut a, &mut b, t, 0); // the ring completes after A's first fold step
    let t = next(&a);
    let quiet = lay(&mut a, &mut b, t, 1);
    assert!(quiet.note_transition.is_some(), "calibration: the quiet block lays the ledger");
    assert_eq!(a.peg().fee_pools().total(), 0, "a quiet block credits nothing (its rows are cover)");
    assert_eq!(b.peg().fee_pools(), a.peg().fee_pools(), "calibration: the pools agree before the spend");
    // The carrier check every door runs (`send_verdict`'s spend arm), measured directly so no earlier gate can answer
    // for it: the protocol fee verifies, any other fee is refused — on both nodes, by the same constant.
    let carrier_pays = |tx: &PqTx, fee: u64| -> bool {
        const PQ: usize = crate::cover::PQ_NOTE_BYTES;
        let cm = |i: usize| crate::spend_frontier::note_cm_of(&tx.output_notes[i * PQ..(i + 1) * PQ]);
        let tag = |i: usize| tx.nullifiers.get(i).and_then(|t| crate::spend_frontier::cm_bytes_to_root(t.as_bytes()));
        match (cm(0), cm(1), tag(0), crate::spend_frontier::cm_bytes_to_root(&tx.membership_leaf_commit), tag(1), Node::tx_filing_d(tx)) {
            (Some(c0), Some(c1), Some(nf), Some(lc), Some(t1), Some(d)) => {
                usdm_decider::verify_spend_validity_carrier_bytes(&tx.blob, c0, c1, nf, lc, d, t1, fee)
            }
            _ => false,
        }
    };
    // TAMPER: a spend proven paying NO fee — its carrier is honest under fee 0 (calibration) and refused under F.
    let free = spend_tx_paying_fee_for_test(&mut a, &mut [&mut b], 0xB140, 999_999_000, 1_000, 0);
    assert!(carrier_pays(&free, 0), "CALIBRATION: the zero-fee carrier is honest under its own fee");
    assert!(!carrier_pays(&free, f), "⛔ §BR-14: a spend that paid no fee passes the door's carrier check");
    let arm = |n: &Node, tx: &PqTx| match n.send_verdict(tx) {
        Ok(a) => a.spend,
        Err(crate::node::SendRefusal::NoArm(a)) => a.spend,
        Err(_) => false,
    };
    assert!(!arm(&b, &free), "⛔ §BR-14: B's send verdict grants the spend arm to a zero-fee carrier");
    let spend = honest_spend_tx_for_test(&mut a, &mut [&mut b], 0xB141);
    assert!(carrier_pays(&spend, f), "calibration: the honest spend's carrier pays the protocol fee");
    // read AFTER the helper funded the input (its funding blocks are spends of their own, each paying its fee)
    let before = a.peg().fee_pools();
    assert_eq!(b.peg().fee_pools(), before, "calibration: the pools agree once the input is funded");
    a.ingest_tx_unverified(spend.clone()).expect("A pools the stated spend");
    let t = next(&a);
    let busy = lay(&mut a, &mut b, t, 2);
    assert!(busy.tx_ids.contains(&spend.id), "calibration: the busy block carries the spend");
    let (pa, pb) = (a.peg().fee_pools(), b.peg().fee_pools());
    eprintln!("[br14] pools before {before:?} · A after {pa:?} · B after {pb:?}");
    assert_eq!(pa, pb, "⛔ §BR-14: the producer and the peer credited different pools");
    assert_eq!(pa.total() - before.total(), u128::from(f), "⛔ §BR-14: one applied spend must credit exactly one protocol fee");
    let (st, bo, su, mi) = crate::peg::fee_split(f);
    assert_eq!(
        (pa.stakers - before.stakers, pa.bonders - before.bonders, pa.surplus - before.surplus, pa.miner - before.miner),
        (st, bo, su, mi),
        "⛔ §BR-14: the credit is not the 40/25/25/10 split"
    );
}

/// ⭐ §BR-3 17.1 + 17.2 — THE PRODUCTION DEFAULTS, MEASURED ON A NODE. The unbonding window a fresh node applies is 21 days at
/// the 500 ms target (3,628,800 blue scores) — longer than theft detection — and governance can set it, never below the
/// merge/fold horizon; the fee split steps the miner pool's share up from the stakers' as the reward halves.
#[test]
fn br3_the_unbonding_window_is_21_days_by_default_and_the_split_follows_the_era() {
    let mut n = Node::new(genesis_block()).unwrap();
    assert_eq!(crate::params::UNBONDING_BLOCKS_DEFAULT, crate::params::blocks_for_ms(21 * crate::params::DAY_MS), "21 days at the derived target");
    assert_eq!(n.unbond_ticks(), crate::params::UNBONDING_BLOCKS_DEFAULT, "a fresh node applies the 21-day window, in chain ticks");
    let horizon = n.params().merge_depth_cap as u64 + n.params().record_fold_depth;
    assert_eq!(n.unbond_horizon_blue(), horizon, "the evidence horizon is the merge/fold depth, in blocks");
    let mut gp = n.params().clone();
    gp.governance_set_unbonding_blocks(0);
    n.set_params(gp);
    // A-F60: the two halves are two gates on two clocks — a governed window of 0 removes the time gate only; the
    // evidence horizon still holds every release for its blocks
    assert_eq!((n.unbond_ticks(), n.unbond_horizon_blue()), (0, horizon), "a governed window of 0 leaves the merge/fold horizon, never less");
    let f = usdm_decider::whir_rec_block::PROTOCOL_FEE_ATOMIC;
    assert_eq!(crate::peg::fee_split_at(f, 0), (40_000, 25_000, 25_000, 10_000), "eras 0–1: 40/25/25/10");
    assert_eq!(crate::peg::fee_split_at(f, 1), (40_000, 25_000, 25_000, 10_000), "eras 0–1: 40/25/25/10");
    assert_eq!(crate::peg::fee_split_at(f, 2), (35_000, 25_000, 25_000, 15_000), "era 2: the miner's 15 % from the stakers' share");
    assert_eq!(crate::peg::fee_split_at(f, 7), (30_000, 25_000, 25_000, 20_000), "era ≥ 3: the miner's 20 %");
}

/// ⭐ §BR-11 — EVERY BLOCK OF A QUARTER PAYS THE RATE, AND THE POOL CONSERVES. Under a governed 6-key quarter, A lays a
/// fee-paying spend in quarter 0 (the miner pool takes 10 % of one fee); the first fold step of quarter 1 closes quarter 0
/// at `rate = accrual / blocks folded in quarter 0`; every block A lays in quarter 1 then carries one `MinerPayout` of
/// exactly that rate, and producer and peer B fold the same payouts: the pool falls by exactly the rate per payout, never
/// below zero, and the payouts plus what the pool keeps equal the quarter-0 credit. Nothing is minted. Ledger-level
/// TAMPERS (the door `apply_miner_payout_at_fold` defers to): an amount above or below the rate, a block of another
/// quarter, and a payout the pool cannot cover are each refused with nothing moved.
/// TWO-PARTY-REVIEWED: A builds and B judges; the assertions are both nodes' pools and payout notes.
#[test]
fn br11_every_block_of_a_quarter_pays_the_rate_and_the_pool_conserves() {
    let (mut a, mut b) = (testnet_party_with_fold_depth(0), testnet_party_with_fold_depth(0));
    for n in [&mut a, &mut b] {
        n.arm_template_double_for_test();
        let mut gp = n.params().clone();
        gp.governance_set_miner_quarter_keys(6);
        n.set_params(gp);
    }
    b.reward_recipient = None;
    let lay = |a: &mut Node, b: &mut Node, tag: u8| -> crate::block::Block {
        let now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + a.params().target_spacing_ms;
        let blk = a.produce(now, Hash32::hash(&[b'Q', tag]), Hash32::hash(&[b'q', tag])).expect("A produces");
        let got = b.ingest_block(blk.clone(), now + 100);
        assert!(matches!(got, crate::relay::RelayOutcome::Added(_)), "B refuses A's block {tag}: {got:?}");
        let _ = b.fold_canonical_records();
        let _ = a.fold_canonical_records();
        blk
    };
    let payouts_in = |blk: &crate::block::Block, a: &Node| -> Vec<crate::miner_payout_tx::MinerPayoutTx> {
        a.opened_credit_objects(blk)
            .unwrap_or_default()
            .iter()
            .filter_map(|o| match crate::chain_object::unframe(o) {
                Some((crate::chain_object::Class::MinerPayout, p)) => crate::miner_payout_tx::MinerPayoutTx::decode(p),
                _ => None,
            })
            .collect()
    };
    lay(&mut a, &mut b, 0);
    lay(&mut a, &mut b, 1);
    let spend = honest_spend_tx_for_test(&mut a, &mut [&mut b], 0xB110);
    a.ingest_tx_unverified(spend.clone()).expect("A pools the fee-paying spend");
    let busy = lay(&mut a, &mut b, 2);
    assert!(busy.tx_ids.contains(&spend.id), "calibration: the spend rides a block");
    let credited = a.peg().fee_pools().miner;
    assert!(credited > 0, "calibration: the miner pool holds a fee share");
    // lay into quarter 1 and through it; record each block's payout as the producer laid it
    let mut laid: Vec<(u64, Vec<crate::miner_payout_tx::MinerPayoutTx>)> = Vec::new();
    // quarter 1 is keys 6..=11 at the 6-key quarter: lay through its last key and stop, so the open quarter stays 1
    for tag in 3..40u8 {
        let blk = lay(&mut a, &mut b, tag);
        let key = crate::satoshi::parent_key_of(a.dag(), &blk.header.parents).map(|(k, _)| k).expect("parent key");
        laid.push((key, payouts_in(&blk, &a)));
        assert_eq!(a.peg().fee_pools(), b.peg().fee_pools(), "⛔ §BR-11: producer and peer hold different pools after block {tag}");
        if key >= 11 {
            break;
        }
    }
    assert_eq!(a.peg().miner_payout_rate().map(|(q, _)| q), Some(1), "calibration: the pin stopped inside quarter 1");
    let (q, rate) = a.peg().miner_payout_rate().expect("a payout quarter is open");
    eprintln!("[br11] credited {credited} · open quarter {q} rate {rate} · pool now {} · laid {:?}",
        a.peg().fee_pools().miner,
        laid.iter().map(|(k, p)| (*k, p.iter().map(|x| x.amount).collect::<Vec<_>>())).collect::<Vec<_>>());
    assert!(rate > 0, "⛔ §BR-11: the closed quarter credited the pool but the next quarter pays nothing");
    let paid: Vec<u64> = laid.iter().flat_map(|(_, p)| p.iter().map(|x| x.amount)).collect();
    assert!(!paid.is_empty(), "⛔ §BR-11: no block of the paying quarter carried a payout");
    assert!(paid.iter().all(|x| *x == rate), "⛔ §BR-11: a payout is not exactly the quarter's rate: {paid:?}");
    assert!(laid.iter().all(|(_, p)| p.len() <= 1), "⛔ §BR-11: a block carried two payouts");
    let total_paid: u64 = paid.iter().sum();
    assert_eq!(total_paid + a.peg().fee_pools().miner, credited, "⛔ §BR-11: payouts plus the pool's remainder are not the credit");
    // TAMPERS at the ledger door the fold defers to
    let mut l = a.peg().clone();
    let pool = l.fee_pools().miner;
    assert!(!l.pay_miner_payout(q, rate + 1), "TAMPER: an amount above the rate");
    assert!(!l.pay_miner_payout(q, rate - 1), "TAMPER: an amount below the rate");
    assert!(!l.pay_miner_payout(q + 1, rate), "TAMPER: a block of another quarter");
    assert_eq!(l.fee_pools().miner, pool, "a refused payout moves nothing");
    let mut drained = l.clone();
    while drained.pay_miner_payout(q, rate) {}
    assert!(drained.fee_pools().miner < rate, "the pool pays until it cannot cover one more rate");
    assert!(!drained.pay_miner_payout(q, rate), "TAMPER: a payout the pool cannot cover");
}

/// ROGUE-ROLE CENSUS fixture (§BR-11): A and B with 6-key quarters and no reward recipient (no producer lays its own payout),
/// the miner pool credited identically on both in quarter 0, then laid into quarter 1 so the quarter's rate is open on both.
/// Returns both nodes, the open quarter and its rate.
fn mp_rogue_setup() -> (Node, Node, u64, u64) {
    let (mut a, mut b) = (testnet_party_with_fold_depth(0), testnet_party_with_fold_depth(0));
    for n in [&mut a, &mut b] {
        n.arm_template_double_for_test();
        n.reward_recipient = None;
        let mut gp = n.params().clone();
        gp.governance_set_miner_quarter_keys(6);
        n.set_params(gp);
    }
    let lay = |a: &mut Node, b: &mut Node, tag: u8| {
        let now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + a.params().target_spacing_ms;
        let blk = a.produce(now, Hash32::hash(&[b'R', tag]), Hash32::hash(&[b'r', tag])).expect("A produces");
        assert!(matches!(b.ingest_block(blk, now + 100), RelayOutcome::Added(_)), "B grafts A's block {tag}");
        let _ = b.fold_canonical_records();
        let _ = a.fold_canonical_records();
    };
    lay(&mut a, &mut b, 0);
    lay(&mut a, &mut b, 1);
    for n in [&mut a, &mut b] {
        assert!(n.peg_mut_for_test().credit_fee_pools(100_000_000), "the miner pool's 10 % share");
    }
    for tag in 2..40u8 {
        if a.peg().miner_payout_rate().is_some_and(|(q, r)| q == 1 && r > 0) {
            break;
        }
        lay(&mut a, &mut b, tag);
    }
    let (q, rate) = a.peg().miner_payout_rate().expect("a quarter is open");
    assert!(q == 1 && rate > 0, "CALIBRATION: quarter 1 pays a rate ({q}, {rate})");
    assert_eq!(b.peg().miner_payout_rate(), Some((q, rate)), "CALIBRATION: one rate on both nodes");
    assert_eq!(a.peg().fee_pools(), b.peg().fee_pools(), "CALIBRATION: one pool on both nodes");
    (a, b, q, rate)
}

/// A payout of `amount` for parent `key`, its note opening to `amount_in_note` under opening key `k`.
fn mp_payout(key: u64, amount: u64, amount_in_note: u64, k: u64) -> crate::miner_payout_tx::MinerPayoutTx {
    let o = usdm_decider::poseidon2_compress::lanes_of(&[0x9a1, k, 2, 3]);
    let cm = usdm_decider::whir_rec_block::asset_note_cm(amount_in_note, usdm_decider::whir_rec_block::USDM_ASSET_TAG, o);
    let mut note = vec![0u8; crate::cover::PQ_NOTE_BYTES];
    note[..32].copy_from_slice(&crate::spend_frontier::leaf_to_cm_bytes(cm));
    crate::miner_payout_tx::MinerPayoutTx {
        key,
        amount,
        note,
        opening: crate::spend_frontier::leaf_to_cm_bytes(o),
        owner_clue: vec![0x5a; crate::peg_in_tx::OWNER_CLUE_MAX],
    }
}

/// The parent key of the next block `b` lays (its tips' largest blue score).
fn mp_next_key(b: &Node) -> u64 {
    let tips: Vec<crate::block::BlockId> = b.dag().tips().into_iter().collect();
    crate::satoshi::parent_key_of(b.dag(), &tips).map(|(k, _)| k).expect("a parent key")
}

/// The rogue `b` lays payout `p` (by hand: its note replaced by its reference) with `payout_nf` of its note in the lane; both
/// judge it (`strip`: the peer may refuse it at the shape door).
fn mp_rogue_judge(a: &mut Node, b: &mut Node, p: &crate::miner_payout_tx::MinerPayoutTx, strip: bool) {
    let mut c = p.clone();
    c.note = crate::chain_object::note_ref(&p.note).expect("a note reference");
    let carriage = crate::chain_object::frame(crate::chain_object::Class::MinerPayout, &c.encode());
    let nf = crate::miner_payout_tx::payout_nf(&p.note_cm().expect("cm"));
    let ts = b.dag().get(&b.selected_tip().expect("tip")).expect("hdr").header.timestamp + b.params().target_spacing_ms;
    let rogue = crate::node::tests::dd_rogue_block_carrying(b, carriage, p.note.clone(), nf, ts, &ts.to_le_bytes());
    for parent in &rogue.header.parents {
        if a.dag().get(parent).is_none() {
            if let Some(sibling) = b.full_block_by_id(parent) {
                let _ = a.ingest_block_preverified(sibling, ts);
            }
        }
    }
    let _ = b.ingest_block_preverified(rogue.clone(), ts);
    let out_a = a.ingest_block_preverified(rogue, ts);
    assert!(
        matches!(out_a, RelayOutcome::Added(_))
            || (strip && matches!(out_a, RelayOutcome::Invalid(crate::consensus::ConsensusError::CreditSetNotCarriage))),
        "CALIBRATION: the rogue block reaches the peer's class door (or, stripped, its shape door): {out_a:?}"
    );
    let _ = a.fold_canonical_records();
    let _ = b.fold_canonical_records();
}

/// CONTROL: an honest payout of the open rate, carried by B for its next parent key, is paid on the peer exactly once.
fn mp_honest_lands(a: &mut Node, b: &mut Node, rate: u64, k: u64) {
    let honest = mp_payout(mp_next_key(b), rate, rate, k);
    assert!(honest.credit_is_authorised(), "CALIBRATION: the honest payout opens its own note");
    mp_rogue_judge(a, b, &honest, false);
    assert_eq!(br_cm_count(a, &honest.note_cm().expect("cm")), 1, "CONTROL: the peer credited the honest payout's note once");
}

/// ⛔⛔⛔ ROGUE-ROLE CENSUS — MinerPayout × FORGE, through a peer: a payout of the rate plus one, its note opening to that
/// amount, carried by the rogue B. The peer's pool and records do not move; CONTROL: an honest payout is then paid once.
#[test]
fn a_miner_payout_above_the_quarters_rate_carried_by_a_rogue_producer_pays_nothing_on_the_peer() {
    let (mut a, mut b, _q, rate) = mp_rogue_setup();
    let forged = mp_payout(mp_next_key(&b), rate + 1, rate + 1, 1);
    mp_rogue_judge(&mut a, &mut b, &forged, false);
    assert!(!a.holds_record_with_cm(&forged.note_cm().expect("cm")), "⛔ ROGUE PRODUCER: the peer credited an over-rate payout");
    mp_honest_lands(&mut a, &mut b, rate, 2);
}

/// ⛔⛔⛔ ROGUE-ROLE CENSUS — MinerPayout × STRIP, through a peer: a payout with its owner clue REMOVED (the codec refuses it,
/// so the rogue lays the bytes by hand). The peer pays nothing; CONTROL: an honest payout is then paid once.
#[test]
fn a_miner_payout_stripped_of_its_owner_carried_by_a_rogue_producer_pays_nothing_on_the_peer() {
    let (mut a, mut b, _q, rate) = mp_rogue_setup();
    let mut stripped = mp_payout(mp_next_key(&b), rate, rate, 3);
    stripped.owner_clue.clear();
    mp_rogue_judge(&mut a, &mut b, &stripped, true);
    assert!(!a.holds_record_with_cm(&stripped.note_cm().expect("cm")), "⛔ ROGUE PRODUCER: the peer credited an ownerless payout");
    mp_honest_lands(&mut a, &mut b, rate, 4);
}

/// ⛔⛔⛔ ROGUE-ROLE CENSUS — MinerPayout × SUBSTITUTE, through a peer: a payout of the rate whose note was swapped for one
/// opening to TEN times the rate under the same opening. The recomputation refuses it; CONTROL: an honest payout is paid once.
#[test]
fn a_miner_payout_whose_note_was_swapped_carried_by_a_rogue_producer_pays_nothing_on_the_peer() {
    let (mut a, mut b, _q, rate) = mp_rogue_setup();
    let swapped = mp_payout(mp_next_key(&b), rate, rate * 10, 5);
    assert!(!swapped.credit_is_authorised(), "CALIBRATION: the swapped note does not open to the stated amount");
    mp_rogue_judge(&mut a, &mut b, &swapped, false);
    assert!(!a.holds_record_with_cm(&swapped.note_cm().expect("cm")), "⛔ ROGUE PRODUCER: the peer credited a note worth ten payouts");
    mp_honest_lands(&mut a, &mut b, rate, 6);
}

/// ⛔⛔⛔ ROGUE-ROLE CENSUS — MinerPayout × REPLAY, through a peer: an honest payout is paid; the rogue B re-carries the SAME
/// payout (same note) in its next block. `payout_nf` is spent, so the peer pays it ONCE.
#[test]
fn a_miner_payout_re_carried_by_a_rogue_producer_is_paid_once_on_the_peer() {
    let (mut a, mut b, _q, rate) = mp_rogue_setup();
    let honest = mp_payout(mp_next_key(&b), rate, rate, 7);
    mp_rogue_judge(&mut a, &mut b, &honest, false);
    let cm = honest.note_cm().expect("cm");
    assert_eq!(br_cm_count(&a, &cm), 1, "CALIBRATION: the honest payout was credited once");
    let again = crate::miner_payout_tx::MinerPayoutTx { key: mp_next_key(&b), ..honest.clone() };
    mp_rogue_judge(&mut a, &mut b, &again, false);
    assert_eq!(br_cm_count(&a, &cm), 1, "⛔ ROGUE PRODUCER: a re-carried payout was credited twice on the peer");
}

/// ⛔⛔⛔ ROGUE-ROLE CENSUS — MinerPayout × BURN, through a peer: a REFUSED payout (over the rate) whose note is the victim's
/// next honest payout note, so its lane names that note's `payout_nf`. It must cost the victim nothing: the peer pays nothing
/// from it, and the honest payout of the same note is then paid on the peer.
#[test]
fn a_refused_miner_payout_naming_a_victims_note_does_not_stop_its_real_payout_on_the_peer() {
    let (mut a, mut b, _q, rate) = mp_rogue_setup();
    let victim = mp_payout(0, rate, rate, 8);
    let refused = mp_payout(mp_next_key(&b), rate + 1, rate, 8); // the victim's note, an amount it does not open to
    assert_eq!(refused.note_cm(), victim.note_cm(), "CALIBRATION: the refused payout names the victim's note");
    mp_rogue_judge(&mut a, &mut b, &refused, false);
    assert!(!a.holds_record_with_cm(&refused.note_cm().expect("cm")), "⛔ ROGUE PRODUCER: the peer credited a refused payout");
    let real = crate::miner_payout_tx::MinerPayoutTx { key: mp_next_key(&b), ..victim };
    mp_rogue_judge(&mut a, &mut b, &real, false);
    assert_eq!(br_cm_count(&a, &real.note_cm().expect("cm")), 1, "⛔ ROGUE PRODUCER: the refused payout burned the victim's real payout"); 
}

/// §RF-3 (R5) — A PRODUCER WITHOUT A COMPLETE ANCHOR RING DEFERS EVERY SPEND: node_c (fresh, never folded — the state
/// after an adopt or a restart whose checkpoint carried no ring) cannot lay the ledger, so a spend it laid would state
/// itself in the legacy per-spend shape (note/member transition bytes and `oli_tags` scale with the spend count).
/// node_c's block carries none of it and the spend stays pooled (deferred, never evicted); node_a, ring complete, lays
/// it in the ledger class and node_b's fold admits its two tags.
/// TWO-PARTY-REVIEWED: node_c and node_a build, node_b's door and fold judge; the assertions are node_c's block and
/// pool and node_b's spent set.
/// §RF-3 CONTENT CENSUS (R5, F2-red-found-20261027k) — the published ledger list is ONE SIZE on every block (28,672 B),
/// but each row's flags `j0 j1 t0 t1` are PUBLIC (`slot_ledger::PUB_FLAGS`, B8 `pubc(PUB_FLAGS, c) - flag`) and the
/// producer justifies every real tag that is no stated spend's row cell (`note_transition::block_ledger_inputs`): a
/// spend's other `TX_FIXED_NULLIFIER_COUNT − 2` constant-width tags ride as justified cells with their bit set. This pin
/// lays a quiet ledger block and one carrying ONE funded honest spend on the same producer and counts both lists' flags;
/// the census answer is that neither count moves with the spend. RED-FIRST — the measured counts are printed beside the
/// verdict. The closure is DB-83 as HIDDEN ledger rows (padding spec §7, §11 item 3: a spend's whole tag set on 16 rows
/// of a class no public bit names), never a bit the door stops reading: the justified bits are the object doors' law.
/// One §BR-11 run for the no-volume-leak census: two fee-paying spends credited in quarter 0 — `together` in ONE block (then
/// an idle block) or one per block — every block `extra_ms` later than the target spacing, then the paying quarter laid
/// through. Returns (the quarter-0 miner credit, the open quarter's rate, every payout's (amount, encoded width) in order).
fn br11_volume_run(together: bool, extra_ms: u64, both: bool) -> (u64, u64, Vec<(u64, usize)>) {
    let (mut a, mut b) = (testnet_party_with_fold_depth(0), testnet_party_with_fold_depth(0));
    for n in [&mut a, &mut b] {
        n.arm_template_double_for_test();
        let mut gp = n.params().clone();
        gp.governance_set_miner_quarter_keys(6);
        n.set_params(gp);
    }
    b.reward_recipient = None;
    let lay = |a: &mut Node, b: &mut Node, tag: u8| -> crate::block::Block {
        let now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + a.params().target_spacing_ms + extra_ms;
        let blk = a.produce(now, Hash32::hash(&[b'V', tag]), Hash32::hash(&[b'v', tag])).expect("A produces");
        assert!(matches!(b.ingest_block(blk.clone(), now + 100), crate::relay::RelayOutcome::Added(_)), "B grafts block {tag}");
        let _ = b.fold_canonical_records();
        let _ = a.fold_canonical_records();
        blk
    };
    lay(&mut a, &mut b, 0);
    let s1 = honest_spend_tx_for_test(&mut a, &mut [&mut b], 0xB121);
    let s2 = honest_spend_tx_for_test(&mut a, &mut [&mut b], 0xB122);
    if together {
        a.ingest_tx_unverified(s1.clone()).expect("A pools spend 1");
        a.ingest_tx_unverified(s2.clone()).expect("A pools spend 2");
        let busy = lay(&mut a, &mut b, 1);
        assert!(busy.tx_ids.contains(&s1.id) && busy.tx_ids.contains(&s2.id), "calibration: both spends ride ONE block");
        lay(&mut a, &mut b, 2);
    } else {
        a.ingest_tx_unverified(s1.clone()).expect("A pools spend 1");
        assert!(lay(&mut a, &mut b, 1).tx_ids.contains(&s1.id), "calibration: spend 1 rides block 1");
        if both {
            a.ingest_tx_unverified(s2.clone()).expect("A pools spend 2");
            assert!(lay(&mut a, &mut b, 2).tx_ids.contains(&s2.id), "calibration: spend 2 rides block 2");
        } else {
            lay(&mut a, &mut b, 2); // the CALIBRATION run: one spend, a different quarterly total
        }
    }
    let credited = a.peg().fee_pools().miner;
    let mut payouts = Vec::new();
    for tag in 3..60u8 {
        let blk = lay(&mut a, &mut b, tag);
        for o in a.opened_credit_objects(&blk).unwrap_or_default() {
            if let Some((crate::chain_object::Class::MinerPayout, p)) = crate::chain_object::unframe(&o) {
                let m = crate::miner_payout_tx::MinerPayoutTx::decode(p).expect("a carried payout decodes");
                payouts.push((m.amount, o.len()));
            }
        }
        let key = crate::satoshi::parent_key_of(a.dag(), &blk.header.parents).map(|(k, _)| k).expect("parent key");
        if key >= 11 {
            break;
        }
    }
    let rate = a.peg().miner_payout_rate().map(|(_, r)| r).unwrap_or(0);
    (credited, rate, payouts)
}

/// ⭐⭐⭐ §BR-11 THE NO-VOLUME-LEAK CENSUS (spec §9 acceptance): two simulated chains with IDENTICAL quarterly fee totals but
/// different per-block volume (both spends in one block vs one per block) and different timing (+0 vs +250 ms per block)
/// pay the SAME rate in the next quarter, in payouts of IDENTICAL amounts and byte width — so a payout reveals one quarterly
/// aggregate and nothing about when, how, or how bunched the quarter's activity was.
/// CALIBRATION: both runs credit a non-zero quarter and pay at least one payout; a third run with ONE spend (a different
/// total) pays a different rate, so the census can tell totals apart.
#[test]
fn br11_two_quarters_with_one_total_and_different_volume_or_timing_pay_one_rate_in_one_shape() {
    let bunched = br11_volume_run(true, 0, true);
    let spread = br11_volume_run(false, 250, true);
    let half = br11_volume_run(false, 0, false);
    eprintln!("[br11-census] bunched {bunched:?} · spread {spread:?} · one spend {half:?}");
    assert_ne!(half.1, bunched.1, "CALIBRATION: a different quarterly total pays a different rate (the census can tell totals apart)");
    assert!(bunched.0 > 0 && !bunched.2.is_empty(), "CALIBRATION: the bunched run credits a quarter and pays it");
    assert_eq!(bunched.0, spread.0, "CALIBRATION: the two runs credit the same quarterly total");
    assert_eq!(bunched.1, spread.1, "⛔ §BR-11: the rate depends on per-block volume or timing, not only on the total");
    assert_eq!(bunched.2, spread.2, "⛔ §BR-11: the payouts' amounts or byte widths differ with the quarter's volume pattern");
}

#[test]
fn rf3_the_published_ledgers_flags_do_not_count_the_blocks_real_spends() {
    let (mut a, mut b) = (testnet_party_with_fold_depth(0), testnet_party_with_fold_depth(0));
    for n in [&mut a, &mut b] {
        n.reward_recipient = None;
        n.arm_template_double_for_test();
    }
    // (Σ j, Σ t) over the 128 published rows — the four flag lanes of every row, nothing else of the list is read.
    let flags = |blk: &crate::block::Block| -> (u64, u64) {
        use usdm_decider::slot_ledger::PUB_FLAGS;
        let nt = blk.note_transition.as_ref().expect("calibration: a ledger block");
        let rows = crate::note_transition::decode_ledger_published(&nt.tuples).expect("calibration: the list decodes");
        let j = rows.iter().map(|r| r[PUB_FLAGS][0] + r[PUB_FLAGS][1]).sum();
        let t = rows.iter().map(|r| r[PUB_FLAGS][2] + r[PUB_FLAGS][3]).sum();
        (j, t)
    };
    let mut now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp;
    let mut lay = |a: &mut Node, b: &mut Node, now: u64, tag: u8| {
        let blk = a.produce(now, Hash32::hash(&[b'g', tag]), Hash32::hash(&[b'n', tag])).expect("A produces");
        let id = blk.id();
        let got = b.ingest_block(blk.clone(), now + 100);
        assert!(matches!(got, crate::relay::RelayOutcome::Added(_)), "calibration: B refuses A's block {tag}: {got:?}");
        assert_eq!(b.selected_tip(), Some(id), "calibration: B does not hold A's tip after block {tag}");
        let _ = b.fold_canonical_records();
        blk
    };
    now += a.params().target_spacing_ms;
    let _ = lay(&mut a, &mut b, now, 0); // the ring completes after A's first fold step
    assert!(a.current_member_ring_commit().is_some(), "calibration: A's ring is complete");
    now += a.params().target_spacing_ms;
    let quiet = lay(&mut a, &mut b, now, 1);
    let (jq, tq) = flags(&quiet);
    let spend = honest_spend_tx_for_test(&mut a, &mut [&mut b], 0x5f4);
    let sid = spend.id;
    a.ingest_tx_unverified(spend).expect("A pools the stated spend");
    now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + a.params().target_spacing_ms;
    let busy = lay(&mut a, &mut b, now, 2);
    assert!(busy.tx_ids.contains(&sid), "calibration: the busy block carries the spend");
    let (jb, tb) = flags(&busy);
    // DIAGNOSTIC: four COUNTS of public bits — no tag, note, amount, key or owner.
    eprintln!(
        "[rf3-flags] quiet Σj {jq} Σt {tq} · one spend Σj {jb} Σt {tb} (a spend carries {} tags, 2 on its own row)",
        crate::cover::TX_FIXED_NULLIFIER_COUNT
    );
    assert_eq!(
        (jb, tb),
        (jq, tq),
        "⛔ R5: the published ledger's flags count the block's real spends — quiet (Σj, Σt) = ({jq}, {tq}), one spend = ({jb}, {tb})"
    );
}

/// §19 (R5, 2026-10-28) — A SEND CARRIES ITS MEMBER LEG AND NO ONE-STEP BIND. The one-step endpoint named the RECORD holding
/// the spent note (`PqTx::membership_tip`, FILED_OPEN: a spend-to-receive join); the ring-anchored member leg (DB-223 Q7,
/// mandatory on every spend) is the record-free membership evidence. The wallet-shaped send with its one-step fields empty
/// passes A's submit door, pools, is laid, and B credits it (the spend's whole tag set admitted); the same send with its
/// member leg stripped too is refused as MembershipMissing (never admitted on no evidence); a one-step bind alone still passes
/// (the legacy form). TWO-PARTY-REVIEWED: A's door and B's graft judge.
#[test]
fn s19_a_send_with_only_its_member_leg_is_admitted_and_credited_on_a_peer() {
    let mut a = testnet_party_folding_at_tip();
    let mut b = testnet_party_folding_at_tip();
    let (note, cm) = Node::test_spendable_note(119);
    let (funding, _) = a.carry_notes_in_a_block_for_test(5_000, &note);
    assert!(matches!(b.ingest_block(funding, 5_500), RelayOutcome::Added(_)), "PRECONDITION: B holds the funding block");
    let mut ts = 6_000u64;
    for i in 0..4u64 {
        if a.member_path_ready_for_test(&cm) && b.member_path_ready_for_test(&cm) {
            break;
        }
        let blk = a.produce(ts, Hash32::hash(&i.to_le_bytes()), Hash32::hash(b"s19-a")).expect("A produces an empty block");
        assert!(matches!(b.ingest_block(blk, ts + 100), RelayOutcome::Added(_)), "PRECONDITION: B grafts it");
        ts += 600;
    }
    assert!(a.member_path_ready_for_test(&cm) && b.member_path_ready_for_test(&cm), "PRECONDITION: the note confirmed on both");
    let (full, _nf) = a.production_spend_tx_for_test(&cm, 119).expect("the wallet-shaped spend builds");
    assert!(!full.membership_carrier.is_empty() && !full.member_carrier.is_empty(), "calibration: both forms present");
    // THE RETIRED FORM DROPPED: no one-step carrier, no one-step tip — the member leg alone.
    let mut leg_only = full.clone();
    leg_only.membership_carrier.clear();
    leg_only.membership_tip.clear();
    let arms = a.send_verdict(&leg_only).expect("⛔ §19: the submit door refuses a send carrying only its member leg");
    assert!(arms.spend && arms.cover, "the spend and spend-or-decoy carriers verify ({arms:?})");
    // TAMPER: no evidence at all — refused, never admitted.
    let mut none = leg_only.clone();
    none.member_carrier.clear();
    none.member_tuple.clear();
    assert!(
        matches!(a.send_verdict(&none), Err(crate::node::SendRefusal::MembershipMissing)),
        "⛔ a send with no membership evidence was admitted"
    );
    // TAMPER: a member leg speaking for another spend (its tuple's binder flipped) — refused.
    let mut foreign = leg_only.clone();
    foreign.member_tuple[0] ^= 1;
    assert!(a.send_verdict(&foreign).is_err(), "⛔ a member leg whose tuple is not this spend's was admitted");
    let id = a.ingest_tx_prechecked(leg_only.clone()).expect("A pools the leg-only send");
    let spent_on_b = |b: &Node| leg_only.nullifiers.iter().filter(|t| b.is_nullifier_spent(t)).count();
    assert_eq!(spent_on_b(&b), 0, "calibration: B holds none of its tags before the block");
    let busy = a.produce(ts, Hash32::hash(b"s19-busy"), Hash32::hash(b"s19-mc")).expect("A lays the busy block");
    assert!(busy.tx_ids.contains(&id), "⛔ the producer did not state the leg-only send");
    let got = b.ingest_block(busy, ts + 100);
    assert!(matches!(got, RelayOutcome::Added(_)), "⛔ B refuses the block: {got:?}");
    let _ = b.fold_canonical_records();
    assert_eq!(
        spent_on_b(&b),
        crate::cover::TX_FIXED_NULLIFIER_COUNT,
        "⛔ B grafted the block but did not admit the leg-only spend's whole tag set"
    );
    assert!(leg_only.membership_tip.is_empty(), "MEASURED: the send named no record (one-step tip 0 B)");
}

/// §19 — AN OBJECT'S MEMBER LEG AT THE SHARED DOOR: orders, deposits, receipts and burns carried the one-step bind naming the
/// RECORD of their note (`Serve::order_book_membership_bind`); `bond_membership_verdict` now takes a member-leg tuple in the
/// tip slot (its width, `MEMBER_TUPLE_BYTES`, no one-step form has): cross-bound to the object (binder, leaf commit, ZERO
/// outputs), anchored in this node's ring, proof verified. A foreign binder is refused; an anchor outside the ring waits at the
/// Admit door and is refused at the Fold door; a flipped carrier byte is refused.
#[test]
fn s19_an_objects_member_leg_verifies_at_the_shared_door_and_every_tamper_is_refused() {
    let mut a = testnet_party_folding_at_tip();
    let (note, cm) = Node::test_spendable_note(121);
    let (_funding, _) = a.carry_notes_in_a_block_for_test(5_000, &note);
    let mut ts = 6_000u64;
    for i in 0..4u64 {
        if a.member_path_ready_for_test(&cm) {
            break;
        }
        let _ = a.produce(ts, Hash32::hash(&i.to_le_bytes()), Hash32::hash(b"s19-b")).expect("A produces");
        ts += 600;
    }
    assert!(a.member_path_ready_for_test(&cm), "PRECONDITION: the note confirmed");
    let k = *Node::test_witness_index().lock().unwrap_or_else(std::sync::PoisonError::into_inner).get(&cm).expect("corpus index");
    let w = Node::test_spend_witness(k);
    let (_, _, nf, _, _) = Node::test_spend_carrier(k, 121).expect("carrier");
    let (carrier, tuple) = a.member_leg_for_test(&cm, nf, w.lc_blind, &[0u8; 32], &[0u8; 32]).expect("the object's member leg builds");
    let mut tip = Vec::with_capacity(crate::member_transition::MEMBER_TUPLE_BYTES);
    crate::member_transition::write_tuple(&tuple, &mut tip);
    assert_eq!(tip.len(), crate::member_transition::MEMBER_TUPLE_BYTES, "calibration: the tuple's width");
    assert!(Node::membership_endpoint_len_ok(tip.len()), "the door's length rule admits a member-leg tip");
    let lc = tuple.leaf_commit;
    let admit = |a: &Node, c: &[u8], t: &[u8], l, b, door| a.bond_membership_verdict(Some((c, t, l, b)), door).0;
    use crate::respend::MemberDoor;
    assert_eq!(admit(&a, &carrier, &tip, lc, nf, MemberDoor::Admit), crate::node::MemberVerdict::Member, "⛔ the honest leg is refused at Admit");
    assert_eq!(admit(&a, &carrier, &tip, lc, nf, MemberDoor::Fold), crate::node::MemberVerdict::Member, "⛔ the honest leg is refused at Fold");
    let mut other = nf;
    other[0] ^= 1;
    assert_eq!(admit(&a, &carrier, &tip, lc, other, MemberDoor::Admit), crate::node::MemberVerdict::Refused, "⛔ a foreign binder passed");
    let mut flipped = carrier.clone();
    let m = flipped.len() / 2;
    flipped[m] ^= 1;
    assert_eq!(admit(&a, &flipped, &tip, lc, nf, MemberDoor::Admit), crate::node::MemberVerdict::Refused, "⛔ a flipped carrier passed");
    let mut outs_tuple = tuple.clone();
    outs_tuple.anchor[0] ^= 1;
    let mut atip = Vec::new();
    crate::member_transition::write_tuple(&outs_tuple, &mut atip);
    assert_eq!(admit(&a, &carrier, &atip, lc, nf, MemberDoor::Admit), crate::node::MemberVerdict::Pending, "an anchor outside the ring waits at Admit");
    assert_eq!(admit(&a, &carrier, &atip, lc, nf, MemberDoor::Fold), crate::node::MemberVerdict::Refused, "⛔ an anchor outside the ring passed at Fold");
}

/// §20 / §20.2 (R5, 2026-10-28) — A SERVED RECORD DOES NOT INVERT TO ITS REAL COUNT. RED-FIRST on the keyless cover
/// (`cover_note_det(blake3(seq ‖ reals), slot)` laid after the reals: a fetcher stripped the reals in ≤ 256 hashes and read
/// the block's real output count — MEASURED 2 reals → 2, node-7x). Under §20.2 the cover bodies are
/// `cover_note_det(record_cover_secret(seq, σ_b), slot)` and the fronts follow `header_seed(reals, σ_b)`, where σ_b is the
/// producer's draw held beside the reals and served to PEERS only: the one public key (the idle key) strips nothing, and
/// no other key is a fetcher's to try. The holder's own key still strips the record to its exact reals (record == serve).
#[test]
fn s20_a_served_record_does_not_invert_to_its_real_count() {
    use crate::cover::{idle_cover_key, strip_fixed_note_payload, BLOCK_FIXED_NOTE_COUNT, PQ_NOTE_BYTES};
    let mut node = testnet_party_folding_at_tip();
    let (note, _cm) = Node::test_spendable_note(131);
    let (blk, _) = node.carry_notes_in_a_block_for_test(5_000, &note);
    let addr = node.record_addr_for_block(&blk.id()).expect("the producer records its block");
    let served = node.da_record_notes(addr).expect("the record is served");
    assert_eq!(served.len(), BLOCK_FIXED_NOTE_COUNT * PQ_NOTE_BYTES, "calibration: the served shape is the constant");
    let reals = node.da_record_reals(addr).map(|r| r.len()).unwrap_or(0);
    assert!(reals >= 1, "calibration: the record holds at least one real note ({reals})");
    let inverted = strip_fixed_note_payload(&served, addr, &idle_cover_key(addr)).map(|r| r.len() / PQ_NOTE_BYTES);
    let holder = strip_fixed_note_payload(&served, addr, &node.cover_key_of(addr)).map(|r| r.len() / PQ_NOTE_BYTES);
    // DIAGNOSTIC: three COUNTS of a locally produced fixture — no note, tag, amount, key or owner.
    eprintln!("[s20] served record: {reals} real(s) held; the public strip reads {inverted:?}; the holder's strip reads {holder:?}");
    assert!(
        inverted.is_none(),
        "⛔ R5: a fetcher of this served record reads the block's real output count ({inverted:?}) — the cover is invertible"
    );
    assert_eq!(holder, Some(reals), "the holder's own key strips the record to its exact reals (record == serve)");
    assert_ne!(node.cover_key_of(addr), idle_cover_key(addr), "calibration: a produced record never wears the public idle key");
}

/// §21.1 (R5, 2026-10-28) — THE OBJECT SIDECARS' ENTRIES ARE PUBLIC ACTS, JUDGED IDENTICALLY ON A PEER. `Block::bond_set`
/// and `Block::dir_set` are 16,384 B on every block, and their entry count is the per-block delta of a set the chain
/// publishes BY DESIGN (the validator set: user ruling 2026-10-07, THORChain-public; the @username namespace). Measured
/// here on a PEER fed only the block over the wire: both sidecars are the constant; each decoded entry is a signed public
/// act (a `PqTx`-framed unbond with its ML-DSA key; a `DirEntry` with its key and signature); the registration lands in the
/// peer's public namespace exactly as in the producer's (the namespace delta IS the entry count), and the unbond — for a
/// validator never bonded — is refused on both, in the open (the validator set is unchanged on both and equal). Nothing in
/// the sidecar says more than the public set does.
#[test]
fn s21_a_sidecars_entries_are_public_acts_judged_identically_on_a_peer() {
    use crate::block::SIDECAR_PADDED_BYTES;
    let mut a = testnet_party_folding_at_tip();
    let mut b = testnet_party_folding_at_tip();
    let need = a.mempool().required_stamp_bits();
    {
        let (pk, sk) = crate::pqauth::ml_dsa_keypair();
        let clue = crate::unbond_tx::unbond_clue_for_test(&[0x21u8; 32], b"s21-unbond");
        let h = crate::unbond_tx::UnbondHeader {
            owner_clue_digest: crate::oli::owner_clue_digest(&clue),
            bond_instance: [0x21u8; 32],
            nonce: [0x22u8; 32],
        };
        let sig = crate::pqauth::ml_dsa_sign(b"s21-unbond", &sk).expect("the validator signs");
        let blob = crate::unbond_tx::wire(&h, &pk, &sig, &clue).expect("the unbond encodes");
        let tx = crate::node::tests::grind_tx(&blob, 0, vec![crate::node::tests::canon_nf_for_test(b"s21-unbond")], need);
        a.ingest_tx_unverified(tx).expect("A pools the unbond");
    }
    let vids_before = (a.validators().every_vid().len(), b.validators().every_vid().len());
    let blk = a.produce(5_000, Hash32::hash(b"s21-f"), Hash32::hash(b"s21-m")).expect("A produces the block");
    assert_eq!(blk.bond_set.len(), SIDECAR_PADDED_BYTES, "CALIBRATION: bond_set is the constant");
    assert_eq!(blk.dir_set.len(), SIDECAR_PADDED_BYTES, "CALIBRATION: dir_set is the constant");
    // the wire form: the body and its key stay behind (serde-skipped); the sidecars travel whole
    let wire: crate::block::Block = postcard::from_bytes(&postcard::to_allocvec(&blk).expect("encodes")).expect("decodes");
    assert!(wire.output_notes.is_empty() && wire.cover_key.is_none(), "CALIBRATION: the wire carries no body and no key");
    // every entry is a signed public act
    let (bond_entries, bond_ok) = Node::bond_set_entries(&wire.bond_set);
    let bonds: Vec<_> = bond_entries.into_iter().flatten().collect();
    assert!(bond_ok && bonds.len() == 1, "CALIBRATION: one well-formed bond-lane entry ({} parsed)", bonds.len());
    let unbond = crate::chain_object::unframe(&bonds[0].blob).and_then(|(_, payload)| crate::unbond_tx::decode(payload));
    assert!(unbond.is_some(), "the bond-lane entry is a signed unbond: a public act");
    // audit F15 (2026-11-10): the directory sidecar carries NOTHING. A sign-up is a paid object in the block's object lane
    // (`Class::DirEntry`; pinned through sibling blocks by `db274_two_nodes_that_apply_two_registrations_...`), so here the
    // sidecar is the constant pad and decodes to no entry at all.
    let dirs = crate::directory::decode_dir_set(&wire.dir_set);
    assert!(dirs.is_empty(), "the directory sidecar carries no entry: {} decoded", dirs.len());
    // the peer judges them in the open, identically — delivered the way every node-to-node lane delivers a block: the
    // gossip envelope (§22/§22b: the hashed block above, plus the cover key and wide objects beside it, node audience only)
    let delivered = crate::block::gossip_decode(&crate::block::gossip_encode(&blk)).expect("the envelope decodes");
    assert_eq!(delivered.id(), wire.id(), "CALIBRATION: the envelope carries the same hashed block");
    assert!(matches!(b.ingest_block(delivered, 5_500), crate::relay::RelayOutcome::Added(_)), "B grafts the block");
    // the directory moves at the FOLD (DB-274), in canonical order on both — drive both folds past the block
    let _ = a.fold_past_for_test(&mut [&mut b], 5_600, b"s21-fold");
    assert_eq!(a.dir_acc(), b.dir_acc(), "both nodes hold one directory after the fold (nothing rode the sidecar into it)");
    assert_eq!(a.dir_log_len(), 0, "and it is empty: no entry reached it without a paid object");
    assert_eq!(
        (a.validators().every_vid().len(), b.validators().every_vid().len()),
        vids_before,
        "an unbond for a validator never bonded changes no public set — refused in the open on both nodes alike"
    );
}

#[test]
fn rf3_a_producer_with_an_incomplete_ring_defers_every_spend_and_a_complete_one_lays_it() {
    let mut node_a = testnet_party_with_fold_depth(0);
    let mut node_b = testnet_party_with_fold_depth(0);
    let mut node_c = testnet_party_with_fold_depth(0);
    for n in [&mut node_a, &mut node_b, &mut node_c] {
        n.reward_recipient = None;
        n.arm_template_double_for_test();
    }
    let tip_ts = |n: &Node| n.dag().get(&n.selected_tip().expect("tip")).expect("hdr").header.timestamp;
    let mut now = tip_ts(&node_a) + node_a.params().target_spacing_ms;
    let blk = node_a.produce(now, Hash32::hash(b"rf3-ring-f0"), Hash32::hash(b"rf3-ring-m0")).expect("node_a produces");
    let got = node_b.ingest_block(blk, now + 100);
    assert!(matches!(got, crate::relay::RelayOutcome::Added(_)), "calibration: node_b grafts block 0: {got:?}");
    let _ = node_b.fold_canonical_records();
    assert!(node_a.current_member_ring_commit().is_some(), "calibration: node_a's ring is complete");
    assert!(!node_c.anchor_ring_is_complete(), "calibration: node_c has never folded — its ring is incomplete");
    let spend = honest_spend_tx_for_test(&mut node_a, &mut [&mut node_b], 0x5f4);
    let sid = spend.id;
    node_c.ingest_tx_unverified(spend.clone()).expect("node_c pools the stated spend");
    let cnow = tip_ts(&node_c) + node_c.params().target_spacing_ms;
    let cblk = node_c.produce(cnow, Hash32::hash(b"rf3-ring-fc"), Hash32::hash(b"rf3-ring-mc")).expect("node_c produces");
    assert!(!cblk.tx_ids.contains(&sid), "⛔ R5: a producer with an incomplete ring laid a spend in the count-stating shape");
    assert!(cblk.note_transition.is_none() && cblk.member_transition.is_none(), "⛔ R5: node_c's block states a transition");
    assert!(node_c.mempool.get(&sid).is_some(), "⛔ the deferred spend left node_c's pool — it must wait, never be evicted");
    node_a.ingest_tx_unverified(spend.clone()).expect("node_a pools the stated spend");
    now = tip_ts(&node_a) + node_a.params().target_spacing_ms;
    let busy = node_a.produce(now, Hash32::hash(b"rf3-ring-f1"), Hash32::hash(b"rf3-ring-m1")).expect("node_a produces");
    assert!(busy.tx_ids.contains(&sid), "⛔ node_a (ring complete) did not lay the spend");
    let class = crate::note_transition::ledger_shape_wire().expect("the ledger class states");
    assert_eq!(busy.note_transition.as_ref().map(|n| n.shape), Some(class), "⛔ R5: the busy block is not the ledger class");
    let got = node_b.ingest_block(busy, now + 100);
    assert!(matches!(got, crate::relay::RelayOutcome::Added(_)), "⛔ node_b refuses node_a's busy block: {got:?}");
    let _ = node_b.fold_canonical_records();
    let spent = spend.nullifiers.iter().filter(|t| node_b.is_nullifier_spent(t)).count();
    // RE-STATED 2026-10-28 (lane funds; read RED "left: 32" since 2026-10-25): the admitted set holds the spend's WHOLE
    // constant width — its row's two tags through the ledger door and its other 30 through the block's spend-or-decoy
    // transition (DB-83; `rf3_a_produced_busy_ledger_block_…` states the same rule) — never fewer, never more.
    assert_eq!(
        spent,
        crate::cover::TX_FIXED_NULLIFIER_COUNT,
        "⛔ R5: node_b grafted the busy block but did not admit the spend's whole constant-width tag set"
    );
}

#[test]
fn rf3_header_cms_from_bodies_are_the_served_slots() {
    for rewarded in [false, true] {
        let mut a = testnet_party_with_fold_depth(0);
        if !rewarded {
            a.reward_recipient = None;
        }
        let now = a.dag().get(&a.selected_tip().expect("tip")).expect("hdr").header.timestamp + a.params().target_spacing_ms;
        let blk = a.produce(now, Hash32::hash(b"rf3-hb-f"), Hash32::hash(b"rf3-hb-m")).expect("A produces a block");
        let served = a.da_record_notes(a.record_addr_for_block_or_canonical(&blk.id())).expect("the record is served");
        let want = crate::note_transition::header_note_cms(&served).expect("256 canonical served slots");
        let got = crate::note_transition::header_note_cms_of_bodies(&blk.output_notes, &kb(&blk)).expect("slots from the body");
        assert_eq!(got, want, "⛔ R5 (rewarded={rewarded}): the body-derived header slots are not the served slots");
        if blk.output_notes.len() >= crate::cover::PQ_NOTE_BYTES {
            let short = &blk.output_notes[crate::cover::PQ_NOTE_BYTES..];
            assert_ne!(
                crate::note_transition::header_note_cms_of_bodies(short, &kb(&blk)),
                Some(want.clone()),
                "calibration: a body missing a real note states the same slots"
            );
        }
    }
}

